<?php $this->layout('default'); use Moves\Services\CmsAudit; use Moves\Support\CmsView as V; $filters = ['q' => V::queryString('q')]; $result = CmsAudit::listing($filters, V::queryPage()); ?>
<div class="cms-card"><form class="cms-filters" method="get"><?= V::field('Evento, registro ou e-mail', 'q', $filters['q'], ['type' => 'search']) ?><button class="cms-btn">Filtrar</button></form><?php if ($result['rows'] === []): ?><?= V::empty('Nenhum evento encontrado.') ?><?php else: ?><div class="cms-table-wrap" tabindex="0" role="region" aria-label="Auditoria"><table><thead><tr><th>Data</th><th>Autor</th><th>Evento</th><th>Registro</th><th>Detalhes</th></tr></thead><tbody><?php foreach ($result['rows'] as $l): ?><tr><td><?= V::date($l['created_at']) ?></td><td><?= V::e($l['actor_email'] ?? 'Sistema') ?></td><td><?= V::e($l['event_type']) ?></td><td><?= V::e($l['resource_type']) ?> <?= V::e($l['resource_id']) ?></td><td><small><?= V::e($l['changes_json']) ?></small></td></tr><?php endforeach; ?></tbody></table></div><?= V::pager($result) ?><?php endif; ?></div>
